"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8187],{8187:a=>{a.exports=JSON.parse('{"slug":"tarify-gaz-elektrichestvo-oktyabr-2026","locale":"ko","title":"2026년 시월 1일 가스가 9,6%, 가정용 전기가 11,3% 올랐습니다","description":"2026년 시월 1일부터 가정용 전기는 11,3%, 가스는 9,6% 비싸졌습니다. 고지서의 구성, 루블 기준 부담, 2027년 칠월 변화를 살펴봅니다.","blocks":[{"id":"b001","kind":"paragraph","text":"2026년 시월 1일 러시아의 가스와 전기가 비싸졌습니다. 가스프롬의 가스 도매가격은 9,6% 올랐습니다. 월 3900kWh 이하를 쓰는 가정의 전기요금은 11,3% 올랐습니다. 러시아 가정용 가스\xb7전기가격은 시장이 아닌 정부가 정합니다. 정부 전망에 정해 둔 일정과 비율에 따라 조정하는 이런 가격을 규제가격이라고 합니다. 그래서 2026년 인상은 일 년 전 정부 경제전망에서도 볼 수 있었습니다."},{"id":"b002","kind":"paragraph","text":"가스 고지서는 세 부분으로 나뉩니다. 가스 자체가 80%, 배관을 통한 가정까지의 운송이 15%, 청구회사의 서비스가 5%입니다. 시월 1일부터 각 항목이 별도로 올라 가스는 9,6%, 운송은 11,6%, 서비스는 5,1% 인상됐습니다. 전체 가스 고지서는 약 9,7% 늘어납니다. 계산은 0,8 \xd7 9,6 + 0,15 \xd7 11,6 + 0,05 \xd7 5,1입니다."},{"id":"b003","kind":"paragraph","text":"전기도 같은 구조로 에너지 자체와 전선을 통한 송전 비용을 합칩니다. 국가기간전력망은 요금을 16%, 지역 배전망은 15,2% 올렸습니다. 가정의 최종 요금은 그보다 작은 11,3% 올랐습니다. 송배전비는 크게 올랐지만 고지서의 일부이기 때문입니다."},{"id":"b004","kind":"paragraph","text":"루블로 보면 가정이 전기에 내던 1000루블마다 113루블, 가스에는 약 97루블이 더 붙습니다. 모스크바의 가스레인지가 있는 아파트에서는 kWh당 요금이 8루블에서 8,9루블로 올랐습니다. 월 200kWh를 쓰면 1600루블 대신 1780루블로 180루블을 더 냅니다. 지역 당국은 연방반독점청이 정한 범위 안에서 가정용 요금을 승인합니다."},{"id":"b005","kind":"paragraph","text":"시월 인상이 마지막은 아닙니다. 2027년 칠월 1일 가스는 당초 계획 9,1% 대신 추가로 10,4% 오릅니다. 연속 두 차례 조정으로 도매가스는 9개월간 약 21% 오릅니다. 계산은 1,096 \xd7 1,104입니다. 2027년 칠월 가정용 배전망 요금은 17,5% 오릅니다. 보통 칠월에 조정하며 2027년부터 그 일정으로 돌아갑니다."},{"id":"b006","kind":"paragraph","text":"일반인의 선택은 이렇습니다. 계량기\xb7절전등\xb7단열은 전기난방 단독주택처럼 고지서가 큰 곳에서 더 빨리 투자비를 회수합니다. 작은 아파트는 회수기간이 깁니다. 2027년 칠월 인상은 이미 한 차례 비율이 바뀌었지만 지금 가계예산에 반영할 수 있습니다."},{"id":"b007","kind":"heading","text":"2026년 시월 1일 가스는 얼마나 올랐나요?"},{"id":"b008","kind":"paragraph","text":"가스 도매가격은 9,6%, 배전망 운송은 11,6%, 가스회사 서비스는 5,1% 올랐습니다. 전체 고지서 상승률은 약 9,7%입니다."},{"id":"b009","kind":"heading","text":"2026년 시월 1일 전기는 얼마나 올랐나요?"},{"id":"b010","kind":"paragraph","text":"월 3900kWh 이하를 사용하는 가정은 11,3% 올랐습니다. 전력망 요금은 더 큰 15,2–16% 올랐습니다."},{"id":"b011","kind":"heading","text":"다음 가스\xb7전기요금 인상은 언제인가요?"},{"id":"b012","kind":"paragraph","text":"2027년 칠월 1일입니다. 가스는 10,4%, 가정용 배전망 요금은 17,5% 오르며 배전망은 전기가격의 일부입니다."}],"sources":[{"label":"가스프롬 규제 가스가격이 9,6% 인상됩니다","url":"https://www.interfax.ru/business/1119546"},{"label":"러시아 연방반독점청이 시월 1일부터 천연가스 요금을 9,6% 조정합니다","url":"https://www.garant.ru/news/1947004/"},{"label":"러시아 배전망 요금은 시월부터 15,2%, 통합전력망은 16% 올랐습니다","url":"https://www.interfax.ru/russia/1119539"},{"label":"연방반독점청이 지역 전기요금을 점검합니다","url":"https://www.kommersant.ru/doc/8990884"},{"label":"2026년 모스크바 전기요금","url":"https://t-j.ru/msk-electroprices/"},{"label":"모스크바 전기요금 2026","url":"https://www.vesti.ru/vj/tarify-na-ehlektroehnergiyu-v-moskve"}],"sourceBodySha256":"b809a176f95ae120cd852b989f922de8a276fc4ea55fc40cff70d0caebfcadd4"}')}}]);